<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/auth.php';
$user=current_user();
if (!$user || !in_array($user['role'],['Administrator','Head'],true)) { http_response_code(403); exit('Access denied.'); }
if ($_SERVER['REQUEST_METHOD']!=='POST') { header('Location: ../?page=students'); exit; }
if (!verify_csrf()) { http_response_code(419); exit('This form has expired. Refresh the page and try again.'); }
$termId=filter_var($_POST['term_id']??null,FILTER_VALIDATE_INT);$sourceForm=filter_var($_POST['source_form']??null,FILTER_VALIDATE_INT);$targetRaw=(string)($_POST['target_form']??'');$targetForm=$targetRaw==='completed'?null:filter_var($targetRaw,FILTER_VALIDATE_INT);$stream=trim((string)($_POST['stream']??''));$reason=trim((string)($_POST['reason']??''));$ids=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['student_ids']??[])),fn($id)=>$id>0)));
$error=null;if(!$termId||!$sourceForm||$sourceForm<1||$sourceForm>6||!$ids)$error='Choose a destination term and at least one learner.';elseif($targetRaw==='completed'&&$sourceForm!==6)$error='Only Form 6 learners can be marked as completing school.';elseif($targetRaw!=='completed'&&(!$targetForm||$targetForm<1||$targetForm>6))$error='Choose a valid destination form.';elseif($targetRaw!=='completed'&&$targetForm<$sourceForm)$error='Progression cannot move learners to a lower form.';elseif(strlen($stream)>20||strlen($reason)>200)$error='Stream or reason is longer than allowed.';
if($error){$_SESSION['error']=$error;header('Location: ../?page=students&progression=1&form='.(int)$sourceForm.'&term_id='.(int)$termId);exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,academic_year,term_number,starts_on FROM school_terms WHERE id=:id FOR UPDATE');$q->execute(['id'=>$termId]);$term=$q->fetch();if(!$term)throw new DomainException('Destination term was not found.');if($targetRaw!=='completed'){$targetClass=$pdo->prepare('SELECT id FROM class_groups WHERE academic_year=:year AND form_level=:form AND stream=:stream FOR UPDATE');$targetClass->execute(['year'=>$term['academic_year'],'form'=>$targetForm,'stream'=>$stream]);if(!$targetClass->fetchColumn())throw new DomainException('Create the destination form and stream under Academics → Classes before progressing learners.');}$find=$pdo->prepare("SELECT s.id,s.form_level,s.stream,s.status,e.id AS enrolment_id,e.start_date FROM students s JOIN student_enrolments e ON e.student_id=s.id AND e.end_date IS NULL WHERE s.id=:id FOR UPDATE");$close=$pdo->prepare('UPDATE student_enrolments SET end_date=DATE_SUB(:start_date,INTERVAL 1 DAY),status=:status,change_reason=:reason WHERE id=:id AND end_date IS NULL');$insert=$pdo->prepare("INSERT INTO student_enrolments(student_id,academic_year,term_number,form_level,stream,start_date,status,change_reason,recorded_by) VALUES(:student,:year,:term,:form,:stream,:start,'Enrolled',:reason,:user)");$update=$pdo->prepare('UPDATE students SET form_level=:form,stream=:stream,status=:status WHERE id=:id');$completed=0;$moved=0;
foreach($ids as $id){$find->execute(['id'=>$id]);$s=$find->fetch();if(!$s||$s['status']!=='Active'||(int)$s['form_level']!==$sourceForm)throw new DomainException('A selected learner is no longer active in the source form. Refresh the list and try again.');if($term['starts_on']<=$s['start_date'])throw new DomainException('The destination term must start after each learner’s current enrollment start date.');if($targetRaw==='completed'){$close->execute(['start_date'=>$term['starts_on'],'status'=>'Completed','reason'=>$reason?:'Completed Form 6','id'=>$s['enrolment_id']]);$update->execute(['form'=>$s['form_level'],'stream'=>$s['stream'],'status'=>'Graduated','id'=>$id]);$completed++;}else{$change=(int)$targetForm>(int)$s['form_level']?'Promoted':'ClassChanged';$close->execute(['start_date'=>$term['starts_on'],'status'=>$change,'reason'=>$reason?:($change==='Promoted'?'Class progression':'Class placement change'),'id'=>$s['enrolment_id']]);$insert->execute(['student'=>$id,'year'=>$term['academic_year'],'term'=>$term['term_number'],'form'=>$targetForm,'stream'=>$stream?:null,'start'=>$term['starts_on'],'reason'=>$reason?:null,'user'=>$user['id']]);$update->execute(['form'=>$targetForm,'stream'=>$stream?:null,'status'=>'Active','id'=>$id]);$moved++;}}
audit_log('students.progressed','students',null,['count'=>$moved,'completed'=>$completed,'source_form'=>$sourceForm,'target_form'=>$targetForm,'term_id'=>$termId]);$pdo->commit();$_SESSION['notice']=($moved+$completed).' learner record(s) progressed successfully; previous class history was retained.';header('Location: ../?page=students&progression=1&form='.(int)$sourceForm.'&term_id='.(int)$termId);exit;
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Student progression failed: '.$e->getMessage());$_SESSION['error']='Progression was not recorded. No selected learner was changed. Check the destination term and try again.';}
header('Location: ../?page=students&progression=1&form='.(int)$sourceForm.'&term_id='.(int)$termId);exit;
